    ('tv-consoles', 'tv-console-unit', 'Low TV Console Unit', 'A clean, low profile with concealed storage.', 'A low TV console with drawers and cabinets to keep devices and accessories out of sight, finished to complement your living room.', '["Sized to your screen","Drawers and cabinets","Cable management openings","Choice of finish"]'::jsonb, '[{"src":"https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=2000&q=80","alt":"Modern living space with sofa and timber details"},{"src":"https://images.unsplash.com/photo-1493663284031-b7e3aefcae8e?auto=format&fit=crop&w=2000&q=80","alt":"Neutral-toned living room with a sofa and wooden furniture"}]'::jsonb, 0),
    ('tv-consoles', 'tv-wall-unit', 'TV Wall Unit', 'A full media wall with display shelving.', 'A complete media wall with a central TV panel, display shelves and storage — turning the TV area into a designed feature of the room.', '["Wall-to-wall designs","Display & closed storage","Concealed wiring","Installed on site"]'::jsonb, '[{"src":"https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=2000&q=80","alt":"Open-plan furnished interior with sofa and dining space"},{"src":"https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=2000&q=80","alt":"Modern living space with sofa and timber details"}]'::jsonb, 1),
