    ('office-furniture', 'office-workstations', 'Office Workstations', 'Configurable desks for productive teams.', 'Workstation clusters configured to your floor plan and team size — with cable management and storage built in.', '["Clusters for any team size","Cable management","Storage pedestals","Planned to your floor"]'::jsonb, '[{"src":"https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=2000&q=80","alt":"Office with desks and workstations"},{"src":"https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=2000&q=80","alt":"Office meeting space with table and chairs"}]'::jsonb, 1),
    ('office-furniture', 'conference-table', 'Conference & Meeting Table', 'Boardroom tables sized for your meetings.', 'Meeting and boardroom tables built to seat your team comfortably, with finishes that present your organisation professionally.', '["Sized to your boardroom","Optional cable ports","Matching credenzas","Delivered & installed"]'::jsonb, '[{"src":"https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=2000&q=80","alt":"Office meeting space with table and chairs"},{"src":"https://images.unsplash.com/photo-1593062096033-9a26b09da705?auto=format&fit=crop&w=2000&q=80","alt":"Executive desk setup"}]'::jsonb, 2)
